insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 1, 'Entretanto huyó David de Nayot, que está cerca de Rámata, y viniendo a verse con Jonatás, prorrumpió en estas palabras: ¿Qué he hecho yo? ¿En qué he pecado, y cuál es mi delito contra tu padre, que anda así buscándome para matarme?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 2, 'Le respondió Jonatás: No temas, no morirás; porque no hará mi padre cosa chica ni grande, sin comunicármela primero. Cómo, ¿esta sola resolución me habría acaso ocultado mi padre? No, de ninguna manera.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 3, 'E hizo sobre ello nuevo juramento a David, asegurándole su amistad. Mas David replicó: Tu padre sabe muy bien que yo he hallado gracia en tus ojos, y habrá dicho: No conviene que sepa esto Jonatás, a fin de que no reciba pesar. Porque yo te juro por el Señor y por tu vida que está tan resuelto tu padre a matarme, que sólo hay un punto, por decirlo así, desde mí a la muerte.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 4, 'Respondió Jonatás a David: Haré por ti todo cuanto me insinuares.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 5, 'Le dijo David: Mira, mañana son las calendas, en que yo, según costumbre, suelo sentarme a la mesa con el rey; ahora, pues, permíteme que vaya a esconderme en el campo hasta la tarde del día tercero.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 6, 'Si tu padre preguntare por mí, le responderás: David me pidió licencia para ir prontamente a Betlehem, su patria; por cuanto todos los de su tribu o familia celebran allí un sacrificio solemne.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 7, 'Si dijere: Bien está; no tendré que temer; pero si se enojare, ten por cierto que su mala voluntad hacia mí ha llegado al colmo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 8, 'Haz, pues, esta merced a tu siervo, ya que quisiste que yo, a pesar de ser tu criado, hiciese contigo y te jurase la más estrecha alianza. Y si adviertes en mí alguna culpa o delito, dame tú mismo la muerte, y no me hagas comparecer delante de tu padre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 9, 'A lo que respondió Jonatás: Libre estás de que te suceda esto; porque no es posible que yo conozca de cierto que el odio de mi padre contra ti ha llegado a lo sumo, sin que yo te lo avise.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 10, 'Replicó David a Jonatás: Y si tu padre por desgracia te diere una respuesta áspera al hablarle de mí, ¿por quién lo sabré?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 11, 'Le respondió Jonatás: Ven y salgamos al campo. Habiendo salido ambos al campo,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 12, 'le dijo Jonatás a David: Señor Dios de Israel si yo mañana u otro día averiguare el designio de mi padre, y resultare algo de bueno a favor de David, y no enviare luego a decírselo, y hacérselo saber,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 13, 'no hagáis, oh Señor, bien a Jonatás, sino mucho mal. Pero si continuare la mala voluntad de mi padre contra ti, te lo avisaré también, y te daré licencia a fin de que te vayas en paz, y el Señor sea contigo, como estuvo con mi padre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 14, 'Y tú, si yo viviere, me tratarás con toda la bondad posible; mas si yo muriere,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 15, 'tendrás siempre compasión y tratarás con bondad a mi familia, cuando el Señor desarraigare uno por uno de la faz de la tierra a todos los enemigos de David. De otra manera, arrebate también el Señor a Jonatás de su casa, y tome Dios venganza de los enemigos de David.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 16, 'De esta suerte hizo Jonatás alianza con la casa de David');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 17, 'Jonatás repitió a David sus juramentos por lo mucho que le quería');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 18, 'Le dijo más: Mañana son las calendas, y serás echado de menos;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 19, 'porque se verá tu asiento vacío aun al día siguiente. Por tanto marcharás luego de aquí, y te dirigirás el primer día después de la fiesta al sitio en que debes esconderte, y te sentarás junto a la peña llamada Ezel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 20, 'Cerca de ella dispararé yo tres saetas, como que me ejercito en tirar al blanco.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 21, 'Enviaré también un muchacho tras ellas, diciéndole: Anda y tráeme las saetas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 22, 'Si yo dijere al muchacho: Mira que las saetas están más acá de ti, cógelas; tú entonces ven a mí, pues es señal de que estás seguro, y vive el Señor que no hay que temer. Mas si dijere yo al criado: Mira, las saetas están más allá de ti, vete en paz, pues el Señor quiere que te retires.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 23, 'En cuanto a lo que tú y yo hemos tratado, sea el Señor para siempre testigo entre los dos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 24, 'Con esto David fue a esconderse en el campo; y llegaron las calendas, y se sentó el rey a comer.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 25, 'Y estando el rey sentado en su silla, que estaba junto a la pared, según costumbre, se levantó Jonatás, y se sentó Abned a un lado de Saúl y se echó de ver vacío el puesto de David.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 26, 'No dijo Saúl nada aquel día');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 27, 'Venido el segundo día de la fiesta, se vio también desocupado el asiento de David. Entonces dijo Saúl a su hijo Jonatás: ¿Por qué no ha venido a comer ni ayer ni hoy el hijo de Isaí?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 28, 'Y respondió Jonatás: Me rogó con mucha instancia que le dejara ir a Betlehem.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 29, 'Diciéndome: Dame licencia; por cuanto se celebra un sacrificio solemne en nuestra ciudad, y me ha convidado, con muchas instancias, uno de mis hermanos; si he hallado, pues, gracia en tus ojos, permíteme dar una vuelta por allí, y ver a mis hermanos. Por ese motivo no ha venido a la mesa del rey.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 30, 'Saúl, indignado contra Jonatás, le dijo: ¡Hijo de prostituta, hijo desamorado y perverso!, ¿piensas que yo ignoro el amor que tienes al hijo de Isaí, para confusión tuya e ignominia de tu envilecida madre?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 31, 'Sábete que mientras viva el hijo de Isaí sobre la tierra, ni tú estarás seguro, ni lo estará tu derecho al reino. Así, pues, envía ahora mismo por él, y tráemelo acá; porque morirá.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 32, 'Mas Jonatás respondió a su padre Saúl diciendo: Pero ¿por qué morirá?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 33, 'Y al oír Saúl esto, agarró la lanza para atravesarle. Entonces conoció Jonatás que su padre tenía resuelto matar a David.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 34, 'Y se levantó Jonatás de la mesa lleno de indignación y de furor, y no comió bocado aquel día segundo de las calendas, apesadumbrado por causa de David, y por la afrenta recibida de su padre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 35, 'Y al rayar el día siguiente fue Jonatás al campo, conforme a lo acordado con David, llevándose consigo un muchacho;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 36, 'al cual dijo: Anda y tráeme las saetas que iré tirando. Estando corriendo el muchacho, disparó otra saeta más lejos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 37, 'Llegado el muchacho al lugar de la primera saeta que había tirado Jonatás, dio éste voces y le gritó: Mira, allá más adelante de ti está la saeta.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 38, 'Le gritó otra vez Jonatás al muchacho, diciéndole: Date prisa, no te detengas. En fin, el muchacho recogió las saetas y se las trajo a su amo,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 39, 'sin entender el motivo de lo que se hacía, porque solamente Jonatás y David lo sabían.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 40, 'Dio después Jonatás sus armas al muchacho, diciéndole: Anda y llévalas a la ciudad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 41, 'Y así que éste hubo marchado, salió David del sitio en que estaba, que miraba al mediodía, e hizo por tres veces una profunda reverencia a Jonatás, postrándose hasta el suelo; y besándose el uno al otro; lloraron juntos; pero David mucho más.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 20, 42, 'En conclusión Jonatás le dijo a David: Vete en paz; todo aquello que los dos hemos jurado en el nombre del Señor, diciendo: El Señor sea testigo entre mí y entre ti, entre mi descendencia y la tuya para siempre...');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 1, 'Y como Saúl volviese de haber perseguido a los filisteos, le avisaron, diciendo: Mira que David está en el desierto de Engaddi.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 2, 'Tomando, pues, Saúl tres mil hombres escogidos en todo Israel, salió en busca de David y de su gente; yendo hasta por las rocas más escarpadas, accesibles sólo a las cabras monteses.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 3, 'Y llegó a unas majadas de ovejas, que encontró en el camino. Había allí una cueva, donde entró Saúl a desocupar el vientre; y David estaba con los suyos escondido en lo más profundo de ella.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 4, 'Le dijeron, pues, a David, sus criados: He aquí el día feliz del cual te dijo el Señor: Yo pondré en tus manos a tu enemigo, para que hagas de él lo que gustares. Entonces David se levantó, y cortó sin ser sentido la orla del manto de Saúl.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 5, 'E inmediatamente le remordió a David su conciencia de haber cortado la orla del manto de Saúl,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 6, 'y dijo a sus compañeros: No permita el Señor que jamás haga yo tal cosa contra mi señor, contra el ungido del Señor, de extender mi mano contra él, siendo como es el ungido del Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 7, 'Y contuvo David con sus palabras a los suyos, no permitiéndoles que se echasen sobre Saúl. Saliendo, pues, éste de la cueva proseguía el camino comenzado;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 8, 'cuando se fue también David en pos de Saúl, y salido ya fuera, dio voces a espaldas de Saúl, diciendo: Mi rey y señor. Volvió Saúl la cabeza, y postrándose David hasta el suelo, le hizo una profunda reverencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 9, 'Y dijo a Saúl: ¿Por qué das oídos a las palabras de aquellos que te dicen: David anda maquinando tu ruina?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 10, 'Hoy ves con tus mismos ojos que el Señor te ha puesto en mis manos en la cueva; me asaltó o me propusieron el pensamiento de matarte; pero me he abstenido de hacerlo, porque dije entre mí: No levantaré yo mi mano contra mi señor; por cuanto es el ungido del Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 11, 'Observa, pues, ¡oh padre mío!, y reconoce si es la orla de tu clámide o manto la que tengo en mi mano, y cómo al cortar la extremidad de tu vestido no he querido extender mi mano contra ti. Considera ahora tú mismo, y persuádete de que no soy culpable en nada, ni de injusticia, ni de pecado contra ti; tú, por el contrario, andas poniendo asechanzas a mi vida para quitármela.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 12, 'Juzgue el Señor entre mí y entre ti, y hágame él justicia respecto de ti; pero yo jamás pondré la mano sobre ti.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 13, 'De impíos es hacer acciones impías, según dice el antiguo proverbio; y así Dios me libre de extender mi mano contra ti.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 14, 'Pero ¿a quién persigues, oh rey de Israel? ¿Quién es al que tú persigues? Persigues a un perro muerto, a una pulga.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 15, 'Sea juez el Señor, y sentencie entre mí y entre ti; examine y juzgue mi causa, y me libre de tus manos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 16, 'Luego que David acabó de hablar tales palabras a Saúl, dijo éste: ¿No es esta voz la tuya, hijo mío David? Y al mismo tiempo lanzó Saúl un grito, y comenzó a llorar.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 17, 'Y dijo a David: Más justo eres tú que yo; porque tú no me has hecho sino bienes, y yo te he pagado con males.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 18, 'Tú has mostrado hoy el bien que me has hecho; puesto que me ha entregado el Señor en tus manos, y no me has quitado la vida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 19, 'Porque, ¿quién es el que hallando a su enemigo desprevenido, le deja ir sin hacerle daño? El Señor te dé la recompensa por lo que hoy has hecho conmigo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 20, 'Y ahora, sabiendo de cierto, como sé, que tú reinarás y poseer el reino de Israel,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 21, 'júrame por el Señor que no extinguirás mi descendencia después de mi muerte, ni borrarás mi nombre de la casa de mi padre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('1-kings', 24, 22, 'Y se lo juró David. Con lo cual se retiró Saúl a su casa');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 1, 'Tres años se pasaron sin guerra entre la Siria e Israel');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 2, 'pero al tercer año fue Josafat, rey de Judá, a visitar al rey de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 3, '(Había dicho el rey de Israel a sus criados o cortesanos: ¿No sabéis que Ramot de Galaad es plaza nuestra, y con todo no cuidamos de recobrarla del poder del rey de Siria?)');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 4, 'Y dijo a Josafat: ¿Vendrás conmigo a la guerra contra Ramot de Galaad?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 5, 'Respondió Josafat al rey de Israel: Somos los dos una misma cosa, y una misma cosa son tu pueblo y el mío, y tuya es mi caballería. Y añadió Josafat al rey de Israel: Consulta, te ruego, al Señor este día, para que sepamos su voluntad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 6, 'Juntó, pues, el rey de Israel a sus profetas en número de cerca de cuatrocientos, y les dijo: ¿Debo emprender la guerra contra Ramot de Galaad, o estarme quieto? Empréndela, respondieron ellos; que el Señor entregará la plaza en poder del rey.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 7, 'Mas Josafat dijo: ¿No hay aquí algún profeta del Señor, a fin de consultar por medio de él?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 8, 'Le respondió el rey de Israel: Uno ha quedado, por cuyo medio podemos consultar al Señor; mas yo lo aborrezco, porque nunca me profetiza cosa buena, sino mala: ése es Miqueas, hijo de Jemla. Replicó Josafat: Oh rey, no hables de esa manera.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 9, 'Llamó, pues, el rey de Israel a un eunuco o camarero y le dijo: Anda, ve, y trae luego a Miqueas, hijo de Jemla.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 10, 'Estaban el rey de Israel y Josafat, rey de Judá, sentados cada uno en su trono, vestidos de traje real en la era o plaza contigua a la puerta de Samaria; y todos los profetas falsos profetizando delante de los dos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 11, 'Y Sedecías, hijo de Canaana, se había hecho fabricar unos cuernos de hierro, y dijo: Esto dice el Señor: Con estos aventarás la Siria, hasta que no dejes rastro de ella.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 12, 'A este tenor los demás profetas profetizaban, diciendo: Sal a campaña contra Ramot de Galaad, ve en hora buena; que el Señor la entregará en manos del rey.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 13, 'Al mismo tiempo el mensajero que había ido a llamar a Miqueas, lo previno, diciendo: Mira que todos los profetas están acordes en anunciar prósperos sucesos al rey; sea, pues, tu lenguaje semejante al suyo, y anuncia buenas nuevas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 14, 'Le respondió Miqueas: Vive el Señor, que no hablaré otra cosa que lo que el Señor me dijere.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 15, 'Llegó, pues, delante del rey, el cual le preguntó: Miqueas, ¿debemos ir a hacer la guerra contra Ramot de Galaad, o estarnos quietos? Le respondió Miqueas: Anda, y ve en hora buena; que el Señor la entregará en manos del rey.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 16, 'Le replicó el rey: Te conjuro una y mil veces en el nombre del Señor, que no me digas sino la verdad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 17, 'Entonces dijo él: Yo vi a todo Israel dispersado por los montes, a semejanza de ovejas sin pastor; y dijo el Señor: Estos no tienen caudillo; vuélvase cada uno en paz a su casa.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 18, 'Al oír esto el rey de Israel dijo a Josafat: ¿Por ventura no te lo dije, que éste jamás me profetiza cosa buena, sino siempre mala?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 19, 'Pero Miqueas, ratificándose, añadió: Por tanto, oye la palabra del Señor: He visto al Señor sentado sobre su solio, y a toda la milicia celestial que estaba a su alrededor a la derecha y a la izquierda.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 20, 'Y dijo el Señor: ¿Quién engañará a Acab, rey de Israel, para que vaya y perezca en Ramot de Galaad? Sobre lo cual uno dijo una cosa, y otro otra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 21, 'Mas salió del abismo el espíritu maligno, y se presentó al Señor, diciendo: Yo lo engañaré si me lo permites. Le preguntó el Señor: ¿De qué manera?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 22, 'Y él respondió: Saldré y seré un espíritu mentiroso en la boca de todos sus profetas. Y dijo el Señor: Lo engañarás, y lograrás tu intento; vete, y haz lo que dices.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 23, 'Mira, pues, concluyó Miqueas; mira que el Señor ha puesto o dejado entrar el espíritu de mentira en la boca de todos tus profetas que están aquí; mientras que el mismo Señor tiene decretados contra ti desastres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 24, 'Se acercó entonces Sedecías, hijo de Canaana, y dio un bofetón a Miqueas, diciendo: ¿Con que a mí me ha desamparado el espíritu del Señor y te ha hablado a ti?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 25, 'Respondió Miqueas: Tú lo verás aquel día, cuando vayas huyendo de escondrijo en escondrijo para ocultarte y salvarte.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 26, 'Pero el rey de Israel dijo: Prended a Miqueas, y esté bajo la custodia de Amón, gobernador de la ciudad, y de Joás, hijo de Amelec;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 27, 'a quienes diréis: Esto manda el rey: Meted a ese hombre en la cárcel, y alimentadle con pan de dolor y agua de aflicción, hasta que yo vuelva victorioso.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 28, 'A lo que dijo Miqueas: Si tú vuelves victorioso, el Señor no habló por mi boca. Y añadió: Pueblos todos estad alerta, y sedme testigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 29, 'Salió, pues, el rey de Israel a campaña con Josafat, rey de Judá, contra Ramot de Galaad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 30, 'Y dijo el rey de Israel a Josafat: Toma tus armas y entra en batalla, vestido de tus ropas. Mas el rey de Israel mudó de traje, y entró disfrazado en la pelea.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 31, 'Había mandado el rey de Siria a los treinta y dos comandantes de sus carros de guerra, diciendo: No pelearéis contra ninguno pequeño ni grande, sino contra solo el rey de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 32, 'Como fuesen, pues, los capitanes de los carros a Josafat, se figuraron que era el rey de Israel, y arrojándose encima, peleaban contra él. Josafat entonces dio voces al Señor;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 33, 'por donde conocieron los capitanes de los carros que no era el rey de Israel, y lo dejaron.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 34, 'Mas un soldado flechó su arco, y disparando al aire, casualmente hirió al rey de Israel entre el pulmón y el estómago. Por lo que dijo el rey a su cochero: Da la vuelta y sácame del combate, porque estoy gravemente herido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 35, 'Se dio, pues, la batalla aquel día; y el rey de Israel, aunque herido, estaba en su carroza, vuelto de cara a los siros. Pero murió por la tarde, habiendo corrido la sangre de la herida hasta el fondo de la carroza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 36, 'Y antes de ponerse el sol, un rey de armas tocó la trompeta por todo el ejército avisando que cada uno se volviese a su ciudad y a su país.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 37, 'Muerto, pues, el rey, fue conducido a Samaria, donde lo sepultaron.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 38, 'Y lavaron su carroza y las riendas de los caballos en el estanque de Samaria; y los perros lamieron su sangre, conforme a la palabra que había el Señor pronunciado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 39, 'Las demás acciones de Acab, y todo cuanto hizo, y la casa de marfil que edificó, y todas las ciudades que fundó, todas estas cosas, ¿no están escritas en el Libro de los Anales de los Reyes de Israel?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 40, 'Pasó finalmente Acab a descansar con sus padres, y lo sucedió en el reino su hijo Ocozías.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 41, 'Josafat, hijo de Asa, había comenzado a reinar sobre Judá el año cuarto de Acab, rey de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 42, 'Treinta y cinco años tenía cuando comenzó a reinar, y reinó veinticinco en Jerusalén. Llamábase su madre Azuba, hija de Salai.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 43, 'Josafat siguió en todo los pasos de su padre Asa, sin desviarse jamás; haciendo lo que era recto delante del Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 44, 'Mas no quitó los lugares altos, pues todavía el pueblo sacrificaba y ofrecía incienso a Dios en las alturas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 45, 'Y el rey Josafat mantuvo la paz con el rey de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 46, 'Las demás cosas de Josafat, y sus hechos y batallas, ¿no está todo esto escrito en el Libro de los Anales de los Reyes de Judá?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 47, 'Además exterminó del país las reliquias de los afeminados, que habían quedado del tiempo de su padre Asa.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 48, 'No había por entonces rey establecido en Idumea.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 49, 'El rey Josafat había formado una flota para hacerla navegar a Ofir, y traer de allí oro; pero no pudo efectuarse, porque naufragaron las naves en Asiongaber.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 50, 'Entonces Ocozías, hijo de Acab, dijo a Josafat: Vaya mi gente a navegar con la tuya; pero Josafat no quiso convenir en ello.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 51, 'Al fin pasó a descansar Josafat con sus padres, y fue sepultado con ellos en la ciudad de su padre David; y lo sucedió en el reino su hijo Joram.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 52, 'Ocozías, hijo de Acab, había comenzado a reinar sobre Israel en Samaria el año décimo séptimo de Josafat, rey de Judá; y reinó sobre Israel dos años.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('3-kings', 22, 53, 'E hizo lo malo delante del Señor, y siguió el camino de su padre y de su madre, y las huellas de Jeroboam, hijo de Nabat, el cual indujo a pecar a Israel. Sirvió también a Baal, y lo adoró, e irritó al Señor Dios de Israel, haciendo todo lo malo que había hecho su padre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 1, '¡Ay de vosotros los que nadáis en la abundancia en medio de Sión, y los que vivís sin ningún recelo en el monte de Samaria!, de vosotros, ¡oh magnates principales de los pueblos, que entráis con fausto en las juntas de Israel!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 2, 'Pasad a la ciudad de Calane, y considerad, y desde allí id a Emat la grande, y bajad a Get de los palestinos, y a los mejores reinos o provincias dependientes de éstos. ¿Tienen ellos más espacioso terreno que vosotros?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 3, 'Pero vosotros estáis reservados para el día calamitoso, y os vais acercando al solio o imperio de la iniquidad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 4, 'Vosotros los que dormís en camas de marfil, y os solazáis en vuestros mullidos lechos; los que coméis los mejores corderos de la grey y los más escogidos becerros de la vacada;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 5, 'los que cantáis al son del salterio y creéis imitar a David usando instrumentos músicos para vuestro deleite');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 6, 'los que bebéis vino en anchas copas, despidiendo preciosos olores, sin compadeceros de la aflicción de José.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 7, 'Por lo mismo irán éstos los primeros a la cautividad, y será dispersado el alboroto de sus banquetes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 8, 'El Señor Dios ha jurado por su vida; ha dicho el Señor Dios de los ejércitos: Yo detesto la soberbia de Jacob, y aborrezco sus palacios, y entregaré al dominio de otros la ciudad con sus habitantes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 9, 'Que si diez hombres quedaren refugiados en una casa, perecerán ellos también.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 10, 'Y algún pariente suyo los tomará uno después de otro, y los quemará, y sacará los huesos fuera de la casa para enterrarlos, y dirá después al que está en el fondo de la casa: ¿Tienes todavía aquí dentro algún otro cadáver? Y responderá el de adentro: No hay más. Y aquel pariente le dirá: Pues calla, y no tienes ya que hacer mención del Nombre del Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 11, 'Porque he aquí que el Señor lo ha decretado, y él castigará la casa grande con la total ruina, y la casa menor con grandes calamidades.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 12, '¿Acaso pueden correr los caballos entre peñas, o se puede arar con indómitos búfalos? Vosotros habéis trocado en opresión el justo juicio, y en ajenjo el fruto de la justicia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 13, 'Vosotros fundáis sobre la nada vuestra alegría, y decís: Pues qué ¿no nos ha hecho poderosos nuestra fortaleza?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('amos', 6, 14, 'Mas he aquí, ¡oh casa de Israel!, que yo levantaré contra vosotros una nación, dice el Señor Dios de los ejércitos, la cual acabará con vosotros desde la entrada de Emat hasta el torrente del desierto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 1, 'En esto apareció un gran prodigio en el cielo, una mujer vestida del sol, y la luna debajo de sus pies, y en su cabeza una corona de doce estrellas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 2, 'Y estando encinta, gritaba con ansias de parir, y sufría dolores de parto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 3, 'Al mismo tiempo se vio en el cielo otro portento; y era un dragón descomunal rojo con siete cabezas y diez cuernos, y en las cabezas tenía siete diademas,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 4, 'y su cola traía arrastrando la tercera parte de las estrellas del cielo, y las arrojó a la tierra; este dragón se puso delante de la mujer, que estaba para dar a luz a fin de tragarse al hijo, luego que ella lo hubiese dado a luz.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 5, 'En esto parió un hijo varón, el cual había de regir todas las naciones con cetro de hierro; y este hijo fue arrebatado para Dios y para su solio.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 6, 'Y la mujer huyó al desierto, donde tenía un lugar preparado por Dios, para que allí la sustenten por espacio de mil doscientos sesenta días.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 7, 'Entretanto se trabó una batalla grande en el cielo: Miguel y sus ángeles peleaban contra el dragón, y el dragón con sus ángeles lidiaba contra él.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 8, 'Pero éstos fueron los más débiles, y después no quedó ya para ellos lugar alguno en el cielo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 9, 'Así fue abatido aquel dragón descomunal, aquella antigua serpiente, que se llama diablo, y también Satanás, que anda engañando a la tierra y fue lanzado y arrojado a la tierra, y sus ángeles con él.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 10, 'Entonces oí una voz sonora en el cielo que decía: He aquí el tiempo de salvación, de la potencia, y del reino de nuestro Dios, y del poder de su Cristo; porque ha sido ya precipitado del cielo el acusador de nuestros hermanos, que los acusaba día y noche ante la presencia de nuestro Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 11, 'Y ellos le vencieron por los méritos de la sangre del Cordero, y en virtud de la palabra de la fe que han confesado, y por la cual desamaron sus vidas hasta perderlas por obedecer a Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 12, 'Por tanto, regocijaos, ¡oh cielos, y los que en ellos morais! ¡Ay de la tierra y del mar!, porque el diablo bajó a vosotros, arrojado del cielo, y está lleno de furor, sabiendo que le queda poco tiempo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 13, 'Viéndose, pues, el dragón precipitado del cielo a la tierra, fue persiguiendo a la mujer, que había dado a luz aquel hijo varón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 14, 'A la mujer se le dieron dos alas de águila muy grande, para volar al desierto a su sitio destinado, en donde es alimentada por un tiempo y dos tiempos, y la mitad de un tiempo, tres años y medio, lejos de la serpiente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 15, 'Entonces la serpiente vomitó de su boca, en pos de la mujer, cantidad de agua como un río, a fin de que la mujer fuese arrebatada por la corriente.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 16, 'Mas la tierra socorrió a la mujer, y abriendo su boca, se sorbió el río que el dragón arrojó de la suya.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('apocalypse', 12, 17, 'Con esto el dragón se irritó contra la mujer, y se marchó a guerrear contra los demás de la casta o linaje de ella, que guardan los mandamientos de Dios, y mantienen la confesión de Jesucristo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 1, 'Venga, pues, mi amado a su huerto, y coma del fruto de sus manzanos. Ya he venido a mi huerto, hermana mía esposa; cogido he ya comido mi panal con la miel mía; bebido he mi vino con mi leche. He dicho: comed vosotros, oh amigos, y bebed, carísimos, hasta saciaros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 2, 'Dormía yo, y estaba mi corazón velando; y he aquí la voz de mi amado que llama y dice: Abreme, hermana mía, amiga mía, paloma mía, mi inmaculada y purísima: Porque está llena de rocío mi cabeza, y de neblina de la noche mis cabellos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 3, 'Y le respondí: ¡Válgame Dios, esposo mío!, si ya me despojé de mi túnica, ¿me la he de volver a poner? Lavé mis pies, ¿y me los he de volver a ensuciar?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 4, 'Entonces mi amado metió su mano por la ventanilla de la puerta probando si la abriría, y a este ruido que hizo se conmovió mi corazón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 5, 'Me levanté luego para abrir a mi amado destilando mirra mis manos, y están llenos de mirra selectísima mis dedos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 6, 'Alcé, pues, la aldaba de mi puerta para que entrase mi amado; pero él se había ya retirado, y seguido adelante. Mi alma había quedado desmayada al eco de su voz; lo busqué, mas no lo hallé; lo llamé a voces, y no me respondió.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 7, 'Me encontraron las patrullas que rondan la ciudad, me hirieron, y me lastimaron; y me quitaron mi manto, con que me cubría, las centinelas de los muros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 8, 'Os conjuro, oh hijas de Jerusalén, que si hallareis a mi amado, le contéis cómo desfallezco de amor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 9, '¿Qué tiene tu amado sobre los demás amados, oh hermosísima entre todas las mujeres?; ¿qué hay en tu querido sobre los demás queridos para que así nos conjures que lo busquemos?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 10, 'Mi amado es blanco y rubio');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 11, 'Su cabeza, oro finísimo; sus cabellos, largos y espesos como renuevos de palmas, y negros como el cuervo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 12, 'Sus ojos como los de las palomas que se ven junto a los arroyuelos de aguas, blancas como si se hubiesen lavado con leche, y que se paran a la orilla de corrientes caudalosísimas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 13, 'Sus mejillas como dos eras de plantas aromáticas, plantadas por hábiles perfumeros; sus labios, lirios rosados que destilan mirra purísima.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 14, 'Sus manos, de oro, y como hechas a torno, llenas de jacintos; su pecho y vientre como un vaso de marfil guarnecido de zafiros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 15, 'Sus piernas columnas de mármol, sentadas sobre basas de oro. Su aspecto majestuoso como el del Líbano, y escogido como cedro entre los árboles.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('canticle-of-canticles', 5, 16, 'Suavísimo el eco de su voz; y en suma, todo él es envidiable. Tal es mi amado, y ése es mi amigo, hijas de Jerusalén.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 1, 'Y respondiendo Job, dijo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 2, 'Muchas veces he oído esas mismas cosas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 3, '¿Cuándo tendrán fin esas palabras? ¿Hay cosa más fácil que hablar como hablas?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 4, 'Bien pudiera yo hablar como vosotros. Mas en verdad que si vuestra alma se hallara en el estado de la mía, yo sé que os consolaría, y que compasivo inclinaría hacia vosotros mi cabeza,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 5, 'os alentaría con mis palabras, y os expresarían mis labios mi compasión.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 6, 'Mas ahora, ¿qué haré? Por más que hable no se mitigará mi dolor; y si guardo silencio, no por eso me dejará.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 7, 'Al presente me ha oprimido el dolor, y están aniquilados todos mis miembros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 8, 'Las arrugas de mi piel dan testimonio contra mí y lo que es más cruel, cierto hombre se vuelve contra mí, contradiciéndome cara a cara con falsos y calumniosos discursos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 9, 'Reúne todo su furor contra mí, y amenazándome rechina sus dientes; hecho enemigo mío, me mira con ojos terribles.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 10, 'Todos mis amigos han abierto contra mí su boca y zahiriéndome con oprobios me han abofeteado');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 11, 'Dios me ha puesto encerrado, a disposición del inicuo, y me ha entregado en manos de los impíos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 12, 'Yo, aquel tan opulento y dichoso algún día, de repente he sido reducido a la nada; me asió de la cerviz el Señor, quebrantándome, y me puso como por blanco de sus tiros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 13, 'Me dejó hecho un erizo con sus dardos, cubrió de heridas mis costados sin piedad alguna, hasta esparcir por el suelo mis entrañas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 14, 'Me ha despedazado con heridas sobre heridas');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 15, 'Yo llevo cosido o pegado a mi piel el cilicio, y he cubierto de ceniza mi cabeza.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 16, 'De tanto llorar está entumecido mi rostro, y se han cubierto de tinieblas las pupilas de mis ojos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 17, 'Todas estas cosas he sufrido, sin que la iniquidad haya manchado mis obras, antes bien ofreciendo puras a Dios mis súplicas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 18, '¡Oh tierra!, no cubras mi sangre, ni sofoques en tu seno mis clamores.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 19, 'Mira que el testigo de mi inocencia está en el cielo, y allí arriba reside el que me conoce a fondo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 20, 'Mis amigos son unos habladores y calumniadores');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 21, '¡Y ojalá que se tratase la causa del hombre con Dios, tan públicamente como se trata la de un hijo del hombre con su competidor!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('job', 16, 22, 'Pues se van pasando a toda prisa mis cortos años, y yo sigo una senda por la cual no volveré ya más.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 1, 'Luego que acabaron de pasar, dijo el Señor a Josué:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 2, 'Escoge doce varones, uno de cada tribu;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 3, 'y mándales que tomen del medio del Jordán, donde estuvieron parados los sacerdotes, doce piedras solidísimas que colocaréis en el lugar del campamento, en que plantaréis esta noche las tiendas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 4, 'Llamó, pues, Josué a los doce varones que había elegido de entre los hijos de Israel, uno de cada tribu,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 5, 'y les dijo: Id delante del Arca del Señor Dios vuestro al medio del Jordán; y traed de allí una piedra cada uno sobre vuestros hombros, conforme al número de las tribus de los hijos de Israel,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 6, 'para que sirvan de monumento entre vosotros; y cuando el día de mañana os preguntaren vuestros hijos, diciendo: ¿Qué significan esas piedras?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 7, 'les habéis de responder: Desaparecieron las aguas del Jordán a vista del Arca del Testamento del Señor, cuando iba ella pasándolo; por esto se pusieron esas piedras para eterno monumento de los hijos de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 8, 'Hicieron, pues, los hijos de Israel lo que les ordenó Josué, trayendo del medio de la madre del Jordán doce piedras, como el Señor le había mandado a Josué, conforme al número de las tribus de los hijos de Israel, hasta el sitio en que acamparon, y las colocaron allí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 9, 'Levantó también Josué otras doce piedras en medio de la madre del Jordán, donde estuvieron parados los sacerdotes que llevaban el Arca del Testamento, y allí permanecen hasta el día de hoy.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 10, 'Entre tanto los sacerdotes, que llevaban el Arca, estaban pasados en medio del Jordán, mientras que se ejecutaban todas las cosas que el Señor había mandado a Josué que comunicara al pueblo, y que le había dicho Moisés. Y el pueblo se dio prisa a pasar el río.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 11, 'Pasado que hubieron todos, pasó también el Arca del Señor, y los sacerdotes marchaban con ella delante del pueblo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 12, 'Así mismo los hijos de Rubén y de Gad, y la media tribu de Manasés iban armados a la frente de los hijos de Israel, como les había mandado Moisés.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 13, 'Y estos combatientes, en número de cuarenta mil, iban delante, ordenados en filas y columnas, por las llanuras y campos de la ciudad de Jericó.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 14, 'En aquel día engrandeció el Señor a Josué delante de todo Israel, para que lo temiesen o respetasen, como habían temido a Moisés mientras vivió.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 15, 'Y les habiá dicho el Señor:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 16, 'Manda a los sacerdotes que llevan el Arca del Testamento, que salgan del Jordán.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 17, 'Josué se lo mandó, diciendo: Salid del Jordán.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 18, 'Y luego que salieron llevando el Arca del Testamento, y comenzaron a pisar la ribera, volvieron las aguas a su madre, y corrieron como solían antes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 19, 'Salió el pueblo del Jordán el día diez del mes primero, y sentó el campamento en Gálgala, que cae al Oriente de la ciudad de Jericó.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 20, 'Colocó asimismo Josué en Gálgala las doce piedras que habían tomado del fondo del Jordán.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 21, 'Y dijo a los hijos de Israel: Cuando preguntaren el día de mañana vuestros hijos a sus padres y les dijeren: ¿Qué significan esas piedras?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 22, 'Los instruiréis y diréis que a pie enjuto pasó Israel ese Jordán,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 23, 'secando el Señor Dios vuestro sus aguas a vuestra vista, hasta que hubisteis pasado; a la manera que primero lo había hecho en el mar Rojo, al cual secó hasta que nosotros pasamos;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 4, 24, 'para que reconozcan todos los pueblos de la tierra la mano todopoderosa del Señor, y vosotros asimismo temáis en todo tiempo al Señor Dios vuestro.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 1, 'Luego que todos los reyes de los amorreos que habitaban a la otra parte del Jordán hacia el Poniente, y todos los reyes de los cananeos que poseían los países vecinos al mar grande o Mediterráneo, oyeron que el Señor había secado las aguas del Jordán, al presentarse los hijos de Israel, hasta que hubieron pasado, desmayó su corazón, y no quedó aliento en ellos, temiendo la entrada de los hijos de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 2, 'En este tiempo, pues, dijo el Señor a Josué: Hazte unos cuchillos de pedernal y restablece otra vez la circuncisión entre los hijos de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 3, 'Hizo Josué lo que el Señor le había mandado, y circuncidó a los hijos de Israel en el collado llamado por eso de la Circuncisión.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 4, 'He aquí, pues, la causa de la segunda circuncisión: todos los varones del pueblo salidos de Egipto, los hombres todos de guerra, murieron en el desierto, durante aquel larguísimo viaje de tantos rodeos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 5, 'Y todos ellos estaban circuncidados. Mas no lo estaban los que habían nacido en el desierto');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 6, 'los cuales anduvieron cuarenta años por aquella vastísima soledad, disponiéndolo así Dios hasta que hubieron muerto todos los que no habían obedecido a la voz del Señor, a quienes juró de antemano que no les dejaría ver la tierra que mana leche y miel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 7, 'Los hijos de éstos sucedieron en el lugar y derechos de sus padres, y fueron circuncidados por Josué; pues estaban incircuncisos, así como habían nacido, no habiéndolos circuncidado ninguno durante el camino.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 8, 'Después que todos fueron circuncidados, se mantuvieron acampados en el mismo sitio, hasta quedar curados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 9, 'Dijo entonces el Señor a Josué: Hoy os he quitado de encima el oprobio de Egipto, y se llamó el nombre de aquel sitio Gálgala, hasta el presente día.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 10, 'Se detuvieron, pues, los lujos de Israel en Gálgala: y celebraron la Pascua el día catorce del mes, a la tarde, en la llanura de Jericó;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 11, 'y al otro día comieron panes ázimos hechos de trigo del país y harina del mismo año.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 12, 'Y luego que ya comieron de los frutos de la tierra, faltó el maná; ni usaron más los hijos de Israel de tal manjar, sino que se alimentaron de los frutos que había producido aquel año la tierra de Canaán.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 13, 'Mientras Josué se hallaba en los alrededores de la ciudad de Jericó, alzó los ojos, y viendo delante de sí un varón que estaba en pie con la espada desenvainada, se encaminó a él y le dijo: ¿Eres tú de los nuestros, o de los enemigos?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 14, 'El cual respondió: No soy lo que piensas: sino que soy el príncipe o caudillo del ejército del Señor, que acabo de llegar. Se postró Josué en tierra, sobre su rostro y adorando a Dios, dijo: ¿Qué es lo que ordena mi Señor a su siervo?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('josue', 5, 15, 'Quítate, le dijo, el calzado de tus pies; pues el lugar que pisas es santo. Y lo hizo Josué como se lo había mandado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 1, '¡Oh varones de Israel!, vosotros que voluntariamente habéis expuesto vuestras vidas, bendecid al Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 2, '¡Escuchad, reyes!, ¡estadme atentos, oh príncipes! Yo soy, yo soy la que celebraré al Señor, y entonaré himnos al Señor Dios de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 3, '¡Oh Señor!, cuando saliste de Seir, y pasaste por las regiones de Edón, se estremeció la tierra, y los cielos y las nubes se disolvieron en aguas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 4, 'Los montes se liquidaron a la vista del Señor, como el monte Sinaí, delante del Señor Dios de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 5, 'En los días de Samgar, hijo de Anat, en los días de Jahel estaban desiertos los caminos; y los que tenían que viajar, andaban por veredas tortuosas o extraviadas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 6, 'Se habían acabado en Israel los valientes, habían desaparecido, hasta que Débora levantó la cabeza y se dejó ver como una madre para Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 7, 'Nuevo y maravilloso modo de guerrear escogió el Señor, y él mismo, por medio de una mujer, destruyó las fuerzas de los enemigos: no se veía lanza ni escudo entre cuarenta mil soldados de Israel.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 8, 'Mi corazón os ama, ¡oh príncipes de Israel!; vosotros que con buena voluntad os expusisteis al peligro, bendecid al Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 9, 'Los que cabalgáis en lucidas caballerías, los que estáis sentados en los tribunales, los que andáis ya libremente por los caminos públicos, hablad vosotros, y bendecid al Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 10, 'Donde se estrellaron los carros de guerra, donde las huestes enemigas se anegaron, allí sean publicadas las venganzas del Señor, y su clemencia para con los valientes de Israel. El pueblo se congregó entonces libremente en las puertas de las ciudades, y recobró su superioridad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 11, '¡Ea, vamos, Débora!, vamos, ea, prepárate para entonar un cántico al Señor! Animo, ¡oh Barac!, ¡vamos, toma, hijo de Abinoem, los prisioneros que has hecho!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 12, 'Se han salvado las reliquias del pueblo de Dios');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 13, 'Se sirvió de uno de la tribu de Efraín para derrotar a los cananeos en la persona de los amalecitas: después se sirvió de una de la tribu de Benjamín contra tus pueblos, ¡oh Amalec! De Maquir, primogénito de Manasés, descendieron los príncipes, y de Zabulón los que han capitaneado hoy el ejército para combatir.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 14, 'También los caudillos de Isacar han ido con Débora y seguido las pisadas de Barac; el cual se ha arrojado a los peligros, dejándose caer sobre el enemigo como quien se despeña a una sima. Mas dividido entonces Rubén en partidos contra sí mismos, se suscitaron discordias entre sus valientes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 15, '¿Por qué te estás ahí quieto, ¡oh Rubén!, entre los dos términos de Israel y de sus enemigos oyendo los balidos de tus rebaños? Pero dividido Rubén en partidos contra sí mismos, sus valientes sólo se ocuparon en disputar entre sí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 16, 'Los de Galaad estaban en reposo a la otra parte del Jordán; y Dan atendía a sus navíos y comercio: lo mismo que Aser que habitaba en la costa del mar, y se mantenía en sus puertos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 17, 'Empero Zabulón y Neftalí fueron a exponer sus vidas en el país de Merome.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 18, 'Vinieron los reyes enemigos y pelearon contra ellos: los reyes de Canaán pelearon contra Israel en Tanac, junto a las aguas del Mageddo; mas no pudieron llevar presa ninguna.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 19, 'Desde el cielo se hizo guerra contra ellos: las estrellas permaneciendo en su orden y curso, pelearon contra Sísara.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 20, 'El torrente de Cisón arrastró sus cadáveres, el torrente de Cadumín, el torrente de Cisón. ¡Huella, oh alma mía, a los orgullosos campeones!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 21, 'Se les saltaron a sus caballos las uñas de los pies con la impetuosidad de la huida, cayendo por los precipicios los más valientes de los enemigos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 22, 'Maldecid a la tierra de Meroz, dijo el ángel del Señor: maldecid a sus habitantes, pues no quisieron venir al socorro del pueblo del Señor, a ayudar a sus más esforzados guerreros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 23, '¡Bendita entre todas las mujeres Jahel, esposa de Haber, cineo, bendita sea en su pabellón!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 24, 'Le pidió Sísara agua, y le dio leche, y en taza de príncipes le ofreció la nata.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 25, 'Con la izquierda cogió un clavo, y con la diestra un martillo de obreros, y mirando donde heriría a Sísara en la cabeza, le dio el golpe y le taladró con gran fuerza las sienes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 26, 'Cayó Sísara entre los pies de Jahel, perdió las fuerzas, y expiró después de haberse revolcado por el suelo delante de Jahel, quedando tendido en tierra, exánime y miserable.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 27, 'Mientras esto pasaba estaba mirando la madre de Sísara desde la ventana y daba voces, diciendo desde su cuarto: ¿Cómo tarda tanto en volver su carro? ¿Cómo son tan pesados los pies de sus cuatro caballos?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 28, 'La más discreta entre las mujeres de Sísara, respondió así a la suegra:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 29, 'Quizá está ahora repartiendo los despojos, y se está escogiendo para él la más hermosa de las cautivas; se separan de entre todo el botín ropas de diversos colores para Sísara, y variedad de joyas para adorno de los cuellos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 30, 'Perezcan, Señor, como Sísara todos tus enemigos: y brillen como el sol en su oriente los que te aman.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('judges', 5, 31, 'Estuvo después todo el país en paz cuarenta años.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 1, 'Llegaron, pues, los hijos de Israel y todo aquel gentío al desierto de Tsin, al mes primero del año cuarenta de la salida de Egipto, e hizo el pueblo su mansión en Cades. Allí murió María, y fue sepultada en el mismo lugar.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 2, 'Y faltando agua al pueblo, se mancomunaron contra Moisés y Aarón,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 3, 'y amotinados dijeron: ¡Ojalá hubiésemos perecido allá entre nuestros hermanos delante del Señor!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 4, '¿Por qué habéis conducido al pueblo escogido del Señor al desierto, para que muramos nosotros y también nuestros ganados?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 5, '¿Por qué nos hicisteis salir de Egipto, y nos habéis traído a este miserable terreno, que no se puede sembrar, que ni da higos, ni vides, ni granadas, y ni aun agua tiene para beber?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 6, 'Con esto Moisés y Aarón, separándose de la gente, y entrando en el Tabernáculo de la alianza, se postraron contra el suelo y clamaron al Señor, y dijeron: ¡Oh Señor, nuestro Dios! escucha los clamores de este pueblo, y ábreles tu tesoro, una fuente de agua viva, a fin de que, apagada su sed, cesen de murmurar. En esto apareció la gloria del Señor sobre ellos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 7, 'Y habló el Señor a Moisés, diciendo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 8, 'Toma la vara, y congregad al pueblo, tú y tu hermano Aarón, y hablaréis a la peña en presencia de toda la gente, y la peña brotará aguas. Y sacado que hubieres agua de la peña, beberá todo el pueblo con sus ganados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 9, 'Tomó, pues, Moisés su vara, que se guardaba en la presencia del Señor, según él se lo mandó,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 10, 'y congregada la multitud delante de la peña les dijo: Oíd, rebeldes y descreídos: ¿Por ventura podremos nosotros sacaros agua de esta peña?');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 11, 'Y habiendo alzado Moisés la mano, y herido dos veces con la vara aquella peña, salieron aguas copiosísimas; de manera que pudo beber el pueblo y los ganados.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 12, 'Dijo entonces el Señor a Moisés y Aarón: Ya que no me habéis creído en orden a hacer conocer mi gloria a los hijos de Israel, no introduciréis vosotros este pueblo en la tierra que yo le daré.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 13, 'Esta es el agua de contradicción, donde los hijos de Israel protestaron contra el Señor, el cual manifestó en ellos su gloria.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 14, 'Entretanto Moisés envió desde Cades embajadores al rey de Idumea, que le dijesen: Esta petición te hace tu hermano Israel: Sabes bien todos los trabajos que hemos padecido;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 15, 'cómo nuestros padres bajaron a Egipto, y allí hemos habitado mucho tiempo, y los egipcios nos maltrataron a nosotros, y a nuestros padres;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 16, 'y cómo clamamos al Señor, y nos oyó, y envió su ángel, el cual nos sacó de Egipto. Ahora hallándonos ya en la ciudad de Cades, situada en tus últimos confines,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 17, 'te suplicamos nos permitas atravesar por tu tierra. No iremos por los campos, ni por las viñas, o beberemos agua de tus pozos, sino que marcharemos por el camino real, sin declinar a la derecha ni a la izquierda, hasta que estemos fuera de tus dominios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 18, 'A lo que respondió el idumeo: No pasarás por mi tierra; que si lo haces, saldré armado a tu encuentro.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 19, 'Replicaron los hijos de Israel: Seguiremos siempre la carretera, y en caso de beber de tus aguas nosotros y nuestros ganados, pagaremos lo justo: no habrá dificultad alguna en el precio; sólo con que nos dejéis pasar a pie.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 20, 'Mas él respondió: No pasaréis. Y luego les salió al encuentro con infinita gente y de mano armada.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 21, 'Y no quiso otorgar lo que le rogaban, que les concediese paso por sus confines. Por cuya causa tiró Israel hacia otra parte.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 22, 'Movido, pues, de Cades el campo, llegaron al monte Hor, que está en los límites de la Idumea;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 23, 'donde habló el Señor a Moisés, diciendo:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 24, 'Vaya Aarón a incorporarse con su pueblo porque no ha de entrar en la tierra que tengo dada a los hijos de Israel');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 25, 'Toma contigo a Aarón y a su hijo con él, y los conducirás al monte Hor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 26, 'Y después de desnudar al padre de sus vestiduras, se las revestirás a su hijo Eleazar. Aarón morirá allí, y será reunido con sus padres.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 27, 'Moisés hizo lo que le mandó el Señor, y subieron al monte Hor a vista de todo el pueblo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 28, 'Donde despojando a Aarón de sus vestiduras, revistió con ellas a Eleazar, su hijo. Muerto aquél sobre la cima del monte, descendió Moisés con Eleazar.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 20, 29, 'Y toda la multitud, así que oyó que Aarón había muerto, hizo duelo por él treinta días en todas sus familias.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 1, 'y dijo además a los príncipes de las tribus de los hijos de Israel: Este es el mandamiento expreso del Señor:');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 2, 'Si algún hombre hiciere voto al Señor, o se obligare con juramento, no quebrantará su palabra; sino que cumplirá todo lo prometido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 3, 'Si una mujer que todavía está en casa de su padre, siendo de menor edad, hace algún voto y se obliga con juramento, si su padre sabe el voto que hizo y el juramento con que obligó su conciencia, y calla, queda obligada al voto;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 4, 'y cuanto prometió y juró, tanto pondrá por obra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 5, 'Pero si el padre luego que le entendió, contradijo serán inválidos así los votos como los juramentos; y no quedará obligada a la promesa; porque se opuso su padre.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 6, 'Si teniendo ya marido, hace algún voto cuando está aún en la casa de sus padres, y saliendo una vez de su boca la palabra ligare su conciencia con juramento,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 7, 'en el día en que lo hubiere oído el marido sin contradecir, quedará obligada al voto y cumplirá todo lo prometido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 8, 'Pero si luego que lo entendió se opuso, e invalidó las promesas y las palabras con que ligó ella su conciencia, el Señor se lo perdonará.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 9, 'La viuda y la repudiada cumplirán todos cuantos votos hicieren.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 10, 'La mujer casada que está en casa de su marido, y se obligare con voto y juramento,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 11, 'si el marido lo sabe, y calla y no se opone a la promesa, cumplirá todo aquello que ha prometido.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 12, 'Pero si desde luego se opone, no le obligará la promesa; porque el marido lo contradijo, y el Señor la dará por absuelta.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 13, 'Si hiciere voto y se obligare con juramento a mortificar su alma con el ayuno o con la abstinencia de otras cosas, quedará al arbitrio del marido el que lo haga o no lo haga.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 14, 'Mas si informado de ello el marido, callare y difiriere su dictamen para otro día, cumplirá la mujer todo lo que votó y prometió, ya que el marido así que lo supo, calló.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 15, 'Pero si se opone después de pasado el día de haberlo sabido, cargará con la culpa de ella.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('numbers', 30, 16, 'Estas son las leyes que dio Dios a Moisés para entre el marido y la mujer, y entre el padre y la hija que todavía es de menor edad, o que aún permanece en la casa paterna.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 1, 'Llamad a vuestros hermanos, Pueblo mío; y a vuestra hermana, La que ha alcanzado misericordia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 2, 'Acusad a vuestra madre, acusadla; porque ya no es mi esposa, ni yo soy su esposo. Aparte de sí sus prostituciones, o idolatrías, y arroje de su seno los adulterios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 3, 'No sea que yo la despoje y desnude, y la ponga tal como en el día que nació, y la deje hecha una soledad, y como una tierra inhabitable, y la reduzca a morir de sed.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 4, 'No tendré compasión de sus hijos, porque son hijos de fornicación.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 5, 'Puesto que la madre de ellos, la nación, es una adúltera, ha quedado deshonrada la que los tuvo. Pues ella dijo: Iré en pos de mis amantes, los ídolos, que son los que me dan mi pan y mi agua, mi lana, mi lino, mi aceite y mi bebida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 6, '(Por lo cual he aquí que yo le cerraré la salida con un seto de espinos, la cerraré con una pared, y ella no hallará paso.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 7, 'E irá en pos de sus amantes, y no los encontrará, los buscará y no los hallará; y dirá: Iré, y volveré a mi primer esposo, pues mejor me iba entonces que ahora).');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 8, 'Y no sabía ella que fui yo, y no los ídolos, quien le dio el trigo, y el vino, y el aceite, y el que le dio la abundancia de plata y de oro que ofrecieron a Baal.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 9, 'Por esto yo me portaré de otro modo, y a su tiempo recogeré mi trigo y mi vino, y quitaré de sus manos mis lanas y mis linos, que cubren sus vergüenzas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 10, 'Y ahora manifestaré su necedad a los ojos de sus mismos amadores, y nadie la liberará de mis manos;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 11, 'y haré cesar todos sus regocijos, sus solemnidades, sus neomenías, sus sábados y todos sus días festivos;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 12, 'y destruiré sus viñas y sus higueras, de las cuales dijo ella: Estos son los galardones que me dieron mis amantes; y yo la convertiré en un matorral, y la devorarán las fieras del campo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 13, 'Y ejerceré en ella mi venganza por los días que sirvió a Baalim, en los cuales le ofrecía incienso, y se ataviaba con sus zarcillos y con sus galas, e iba en pos de sus amantes, y se olvidaba de mí, dice el Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 14, 'Pero con todo, después yo la acariciaré, y la llevaré a la soledad, y le hablaré al corazón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 15, 'Le daré viñadores de su mismo lugar, y el valle de Acor, para que entre en esperanza; y allí cantará himnos a su Dios como en los días de su juventud, como en los días en que salió de la tierra de Egipto.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 16, 'Y aquel será el día, dice el Señor, en que ella me llamará esposo suyo; y no me llamará más Baalí.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 17, 'Y quitaré de su boca los nombres de Baalim, y no volverá a acordarse más de los nombres de los ídolos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 18, 'Y en aquel día pondré yo paz entre ellos, y las bestias del campo, y las aves del cielo, y los reptiles de la tierra; y quebrantaré en el país los arcos y las espadas, y haré cesar las guerras, y que ellos duerman con toda seguridad.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 19, 'Y te desposaré conmigo para siempre y te desposaré conmigo mediante la justicia o santidad y el juicio, y mediante la misericordia y la clemencia.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 20, 'Y te desposaré conmigo mediante la fe, y conocerás que yo soy el Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 21, 'Entonces será, dice el Señor, cuando yo escucharé benigno a los cielos, y éstos escucharán a la tierra.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 22, 'Y la tierra atenderá a dar el grano, y el vino, y el aceite; y estas cosas atenderán o consolarán a Jezrael.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 2, 23, 'Y la sembraré yo para mí como preciosa simiente sobre la tierra, porque me apiadaré de aquella nación que fue llamada: No más misericordia. Y al que dije que no era mi pueblo, le diré: Pueblo mío eres tú; y él dirá: Tú eres mi Dios.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 14, 1, '¡Oh Israel!, conviértete al Señor Dios tuyo; porque por tus maldades te has precipitado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 14, 2, 'Pensad en lo que diréis al Señor. Convertíos a él, y decidle arrepentidos: Quita de nosotros toda iniquidad, acepta este bien, o buen deseo nuestro, y te presentaremos la ofrenda de nuestras alabanzas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 14, 3, 'No confiaremos ya en que el asirio nos salve, no montaremos confiados en los caballos de los egipcios, no llamaremos en adelante dioses nuestros a las obras de nuestras manos: porque tú, ¡oh Señor!, te apiadarás de este pueblo como de un huérfano que se pone en tus manos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 14, 4, 'Yo curaré sus llagas, responde el Señor, los amaré por pura gracia; por cuanto se ha aplacado mi indignación contra ellos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 14, 5, 'Seré como el rocío para Israel; el cual brotará como el lirio, y echará raíces como un árbol del Líbano.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 14, 6, 'Se extenderán sus ramas; será bello y fecundo como el olivo, y odorífero como el árbol del incienso.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 14, 7, 'Se convertirán al Señor, y reposarán bajo su sombra; se alimentarán del trigo; se propagarán como la vid; la fragancia de su nombre será como la del vino del Líbano.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 14, 8, 'Efraín dirá entonces: ¿Qué tengo yo ya que ver con los ídolos? Y yo le escucharé benignamente, yo lo haré crecer como un alto y verde abeto; de mí tendrán origen tus frutos, ¡oh Israel!');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('osee', 14, 9, '¿Quién es el sabio que estas cosas comprenda? ¿Quién tiene talento para penetrarlas? Porque los caminos del Señor son rectos, y por ellos andarán los justos; mas los prevaricadores hallarán en ellos su ruina.');
